export type Kana = { c: string; r: string }
export type KanaLesson = { id: string; script: 'hiragana' | 'katakana'; title: string; tip: string; chars: Kana[]; words: { w: string; r: string; en: string }[] }

const k = (pairs: string): Kana[] => pairs.trim().split(/\s+/).map(p => { const [c, r] = p.split(':'); return { c, r } })

